/// <summary>
/// PaffH 11.02.22
/// generate production labels 
/// </summary>
void endUpdateProduction()
{
    next endUpdateProduction();
    if (NDXProdStatusChangedGenerateTransportLabelEventContractInteraction::GenerateLabelForPA(prodTable.ProdId))
    {
        try
        {
            Global::runAsync(classNum(NDXProdStatusChangedGenerateTransportLabelEventContractInteraction),
                    staticMethodStr(NDXProdStatusChangedGenerateTransportLabelEventContractInteraction,triggerEvent ),
                    [prodTable.ProdId],
                    System.Threading.CancellationToken::None,
                    classNum(NDXProdStatusChangedGenerateTransportLabelEventContractInteraction),
                    staticMethodStr(NDXProdStatusChangedGenerateTransportLabelEventContractInteraction,TriggerEventCallback ));
        }
        catch
        {
            error(Error::wrongUseOfFunction(funcName()));
        }
    }
    if (prodTable.ProdStatus == ProdStatus::Released)
    {
        NDXSNLTask::checkPDMTask(NDXSNLEvent::ProdTableScheduled, prodTable);
    }
}

/// <summary>
/// PaffH 12.12.24
/// </summary>
void printout()
{
    next printout();
    if (prodParmRelease.NDXPrintProdProdIdent == NoYes::Yes)
    {
        NDXSSRSReportProdTableProdIdentController::constructFromProdUpdRelease(prodParmRelease);
        NDXProdTableProdIdentReport::findOrCreateUpdate(prodParmRelease.ProdTable(), true);
    }
}
